ial,sans-serif}.cm-sim-data-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;margin-bottom:20px;padding:16px;background:#fdf6ec;border-radius:3px;border:1px dashed #d9c7ad}.cm-sim-data-item{display:flex;justify-content:space-between;font-size:.88rem;padding:6px 0;border-bottom:1px dotted #d9c7ad}.cm-sim-container .cm-sim-data-k{color:#6e4a31;font-family:'Helvetica Neue',Arial,sans-serif;font-size:.78rem}.cm-sim-container .cm-sim-data-v{font-weight:700;color:#2b2118}.cm-sim-container .cm-sim-submit{background:#d17b47;border:none;color:#fff;padding:12px 32px;border-radius:3px;font-family:'Helvetica Neue',Arial,sans-serif;font-weight:700;font-size:.82rem;letter-spacing:.18em;text-transform:uppercase;transition:background .2s ease,transform .1s ease;margin-right:12px}.cm-sim-container .cm-sim-submit:hover{background:#b5632f;transform:translateY(-1px)}.cm-sim-container .cm-sim-undo{background:transparent;border:1px solid #8a7560;color:#6e4a31;padding:10px 20px;border-radius:3px;font-family:'Helvetica Neue',Arial,sans-serif;font-size:.75rem;letter-spacing:.14em;text-transform:uppercase}.cm-sim-history{background:#fff;border-radius:4px;padding:20px 24px;margin-bottom:24px;box-shadow:0 4px 14px rgba(59,42,31,0.08)}.cm-sim-container .cm-sim-history h3{font-family:'Helvetica Neue',Arial,sans-serif;font-size:.8rem;letter-spacing:.22em;text-transform:uppercase;color:#d17b47;font-weight:700;margin-bottom:14px}.cm-sim-container .cm-sim-history table{font-size:.88rem;color:#2b2118}.cm-sim-container .cm-sim-history th{background:#3b2a1f;color:#fdf6ec;font-family:'Helvetica Neue',Arial,sans-serif;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;font-weight:600;padding:10px 12px;border:none}.cm-sim-container .cm-sim-history td{padding:10px 12px;border-bottom:1px solid #f0e6d5}.cm-sim-chart-wrap{background:#fff;border-radius:4px;padding:24px;box-shadow:0 4px 14px rgba(59,42,31,0.08);height:340px}@media (max-width:768px){.cm-sim-container{padding:16px}.cm-sim-container .cm-sim-header h1{font-size:1.5rem}.cm-sim-period-bar{flex-direction:column;gap:8px;align-items:flex-start}.cm-sim-kpi-grid{grid-template-columns:repeat(2,1fr)}.cm-sim-container .cm-sim-kpi-value{font-size:1.3rem}}.cm-sim-container .cm-sim-help{font-family:'Helvetica Neue',Arial,sans-serif;font-size:.75rem;line-height:1.45;color:#8a7560;margin-top:6px}
