      var caseCpl = this._cpl(80, CASE.deployedFrac6m, CASE.leads6m);
      var set = function (id, txt) { var e = document.getElementById(id); if (e) e.textContent = txt; };
      set('dBlogVal', this._num(CASE.traffic6m) + ' / mes');
      set('dLeadsVal', String(CASE.leads6m));
      set('dCplVal', 'COP ' + caseCpl.toFixed(2) + 'M');
    }

    _updateBriefing(state) {
      var sim = window.mySimulation;
      var maxP = (sim && sim.state && sim.state.maxPeriods) || 4;
      var ds = (sim && sim.state && sim.state.domainState) || {};
      var p = state.currentPeriod || 1;
      var rt = document.getElementById('roundTitle');
      var bt = document.getElementById('briefingTitle');
      var bx = document.getElementById('briefingText');

      if (p > maxP) {
        var perf = ds.performance || { overallScore: 0, grade: 'F' };
        if (rt) rt.textContent = this._t('done_title');
        if (bt) bt.textContent = this._t('done_brief_t');
        if (bx) bx.innerHTML = this._fmt(this._t('done_brief'), {
          score: Math.round(perf.overallScore || 0), grade: perf.grade || 'F',
          points: Math.round(ds.score || 0), max: MAX_POINTS
        });
      } else {
        var round = this.ROUNDS[Math.min(p - 1, this.ROUNDS.length - 1)];
        if (rt) rt.textContent = this._t(round.titleKey);
        if (bt) bt.textContent = this._t(round.briefTitleKey);
        if (bx) {
          var params = null;
          if (p === 2) {
            params = {
              plan_traffic: this._num(ds.planTraffic || 0),
              plan_leads: this._num(ds.planLeads || 0),
              case_traffic: this._num(CASE.traffic6m),
              case_leads: String(CASE.leads6m),
              case_cpl: this._cpl(80, CASE.deployedFrac6m, CASE.leads6m).toFixed(2)
            };
          }
          bx.innerHTML = this._fmt(this._t(round.briefTextKey), params);
        }
      }
      for (var i = 1; i <= 4; i++) {
        var el = document.getElementById('panelR' + i);
        if (el) el.style.display = (i === p) ? 'block' : 'none';
      }
      if (p === 2) this._fillCaseGrid(ds);
    }

    /* --------------------------- validation -------------------------------- */

    validateDecisions(decisions) {
      var sim = window.mySimulation;
      var st = sim.state;
      var p = st.currentPeriod || 1;
      var self = this;
      var warn = function (key) {
        sim.uiManager.showNotification(self._t(key), 'warning');
        return false;
      };
      var el = function (id) { return document.getElementById(id); };

      if (p === 1) {
        var dp = el('distPctInput'), fs = el('focusSelect'), ps = el('pillarSelect');
        if (dp) decisions.distPct = parseFloat(dp.value);
        if (fs) decisions.focus = fs.value;
        if (ps) decisions.pillar = ps.value;
        if (isNaN(decisions.distPct) || decisions.distPct < 0 || decisions.distPct > 60) return warn('warn_dist');
        if (FOCUS.indexOf(decisions.focus) < 0) return warn('warn_focus');
        if (PILLARS.indexOf(decisions.pillar) < 0) return warn('warn_pillar');
      } else if (p === 2) {
        var dsel = el('diagSelect');
        if (dsel) decisions.diagnosis = dsel.value;
        if (DIAGS.indexOf(decisions.diagnosis) < 0) return warn('warn_diag');
      } else if (p === 3) {
        var pv = el('pivotSelect'), hz = el('horizonSelect');
        if (pv) decisions.pivot = pv.value;
        if (hz) decisions.horizon = parseInt(hz.value, 10);
        if (PIVOTS.indexOf(decisions.pivot) < 0) return warn('warn_pivot');
        if (HORIZONS.indexOf(decisions.horizon) < 0) return warn('warn_horizon');
      } else if (p === 4) {
        var ks = el('kpiSelect'), pi = el('pitchInput');
        if (ks) decisions.kpi = ks.value;
        if (pi) decisions.pitch = (pi.value || '').trim();
        if (KPIS.indexOf(decisions.kpi) < 0) return warn('warn_kpi');
        if (!decisions.pitch || decisions.pitch.length < 10) return warn('warn_pitch');
        if (this._words(decisions.pitch) < 3) return warn('warn_pitch_words');
      }
      this._updateBriefing(st);
      return true;
    }

    /* ----------------------------- model ----------------------------------- */

    calculateResults(state) {
      var d = state.decisions;
      var ds = state.domainState;
      var p = state.currentPeriod;
      var traffic = ds.traffic, leads = ds.leads, brand = ds.brandScore, budget = ds.budget;
      var deployedFrac = 1, roundScore = 0, summary = '';

      if (p === 1) {
        var base = 1400;
        var distBoost = 1 + ((d.distPct - 25) * 0.018);
        var focusMult = d.focus === 'educational' ? 1.15 : (d.focus === 'sales' ? 0.85 : 1.0);
        var pillarMult = d.pillar === 'retirement' ? 1.1 : (d.pillar === 'family' ? 1.05 : (d.pillar === 'wellbeing' ? 1.0 : 0.85));
        traffic = Math.round(base * distBoost * focusMult * pillarMult);
        var leadRate = d.focus === 'sales' ? 0.018 : (d.focus === 'mixed' ? 0.012 : 0.007);
        leads = Math.round(traffic * 6 * leadRate);
        brand = 50 + (d.focus === 'educational' ? 6 : (d.focus === 'mixed' ? 3 : -2));
        deployedFrac = CASE.deployedFrac6m;
        /* round 1 output is the PLAN's projection; round 2 contrasts it with reality */
        ds.planTraffic = traffic;
        ds.planLeads = leads;
        if (d.distPct >= 20 && d.distPct <= 35) roundScore += 25; else roundScore += 10;
        if (d.focus === 'mixed') roundScore += 25;
        else if (d.focus === 'educational') roundScore += 18;
        else roundScore += 15;
        if (d.pillar === 'family' || d.pillar === 'retirement') roundScore += 20; else roundScore += 10;
        summary = this._t('sum_r1');
      } else if (p === 2) {
        /* the 6-month actuals are fixed case data — that is the point of the round */
        traffic = CASE.traffic6m;
        leads = CASE.leads6m;
        brand = 50;
        deployedFrac = CASE.deployedFrac6m;
        if (d.diagnosis === 'funnel') roundScore = 40;
        else if (d.diagnosis === 'vanity') roundScore = 25;
        else if (d.diagnosis === 'patience') roundScore = 15;
        else roundScore = 10;
        summary = this._t('sum_r2_' + d.diagnosis);
      } else if (p === 3) {
        if (d.pivot === 'A') {
          budget = 80 + 15;                       /* the option promises +COP 15M */
          traffic = Math.round(traffic * 2.1);
          leads = Math.round(leads * 1.8);
          brand = brand + 2;
          roundScore = d.horizon === 6 ? 30 : (d.horizon === 12 ? 25 : 15);
        } else if (d.pivot === 'B') {
          traffic = Math.round(traffic * 1.15);
          leads = Math.round(leads * 3.2);
          brand = brand - 6;
          roundScore = d.horizon === 3 ? 35 : (d.horizon === 6 ? 28 : 18);
        } else {
          traffic = Math.round(traffic * 1.4);
          leads = Math.round(leads * 2.5);
          brand = brand + 12;
          roundScore = d.horizon === 12 ? 45 : (d.horizon === 6 ? 35 : 15);
        }
        summary = this._t('sum_r3_' + d.pivot);
      } else if (p === 4) {
        var pivot = d.pivot || 'C';
        var alignment = { A: 'traffic', B: 'leads', C: 'revenue' }[pivot];
        if (d.kpi === alignment) roundScore = 40;
        else if (d.kpi === 'revenue' || d.kpi === 'leads') roundScore = 28;
        else roundScore = 15;
        /* argued, not padded: 6+ distinct words, not 40 raw characters */
        if (this._words(d.pitch) >= 6) roundScore += 10;
        summary = this._t('sum_r4_' + d.kpi);
      }

      var cpl = this._cpl(budget, deployedFrac, leads);
      ds.budget = budget;
      ds.traffic = traffic;
      ds.leads = leads;
      ds.brandScore = Math.max(0, Math.min(100, brand));
      ds.cpl = cpl;

      /* write by period index (never push) so undo + replay cannot double-count */
      var i = p - 1;
      ds.roundScores[i] = roundScore;
      ds.roundScores.length = p;
      ds.score = ds.roundScores.reduce(function (a, b) { return a + (b || 0); }, 0);
      ds.scoreHistory[i] = ds.score; ds.scoreHistory.length = p;
      ds.trafficHistory[i] = traffic; ds.trafficHistory.length = p;
      ds.leadsHistory[i] = leads; ds.leadsHistory.length = p;
      ds.brandHistory[i] = ds.brandScore; ds.brandHistory.length = p;

      /* the field the PHP grading layer actually reads (express_resolveDomainScore) */
      var norm = this._normalize(ds.score);
      ds.performance = { overallScore: norm, grade: this._letter(norm), points: ds.score, maxPoints: MAX_POINTS };

      var self = this;
      setTimeout(function () { self._updateBriefing({ currentPeriod: p + 1 }); }, 400);

      return {
        period: p, roundScore: roundScore, totalScore: ds.score,
        overallScore: norm, grade: ds.performance.grade,
        traffic: traffic, leads: leads, cpl: cpl, brand: ds.brandScore, summary: summary
      };
    }

