    getHint(state, results) {
      if (!results) return null;
      /* the framework has already advanced currentPeriod — key off the round played */
      var r = results.period;
      var d = state.decisions || {};
      if (r === 2 && d.diagnosis !== 'funnel') return this._t('hint_funnel');
      if (r === 3 && d.pivot === 'A') return this._t('hint_pivotA');
      if (r === 3 && d.pivot === 'B' && d.horizon === 12) return this._t('hint_pivotB');
      if (r === 4 && d.kpi === 'traffic') return this._t('hint_kpi_traffic');
      if (results.roundScore >= 40) return this._t('hint_great');
      if (results.roundScore <= 15) return this._t('hint_weak');
      return null;
    }

