      ];
    }

    getPresets() { return null; }

    getPerformanceSummary(history) {
      if (!history || !history.length) return {};
      var points = history.reduce(function (s, r) { return s + ((r.results && r.results.roundScore) || 0); }, 0);
      var norm = this._normalize(points);
      var last = history[history.length - 1] || {};
      var d = last.decisions || {};
      var perf = norm >= 85 ? this._t('tier_excellent')
        : norm >= 70 ? this._t('tier_solid')
          : norm >= 50 ? this._t('tier_ok') : this._t('tier_beginner');
      var aligned = { A: 'traffic', B: 'leads', C: 'revenue' }[d.pivot || 'C'];
      var insights = [];
      insights.push(d.diagnosis === 'funnel' ? this._t('ins_funnel_ok') : this._t('ins_funnel_miss'));
      insights.push(d.kpi === aligned ? this._t('ins_kpi_ok') : this._t('ins_kpi_miss'));
      if (norm < 70) insights.push(this._t('ins_low'));
      insights.push(this._t('ins_always'));
      return {
        totalScore: norm, overallScore: norm, points: points, maxPoints: MAX_POINTS,
        performance: perf, grade: this._letter(norm), insights: insights
      };
    }

